using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;

namespace RogControl {
 public partial class MainWindow {
  string selectedKeyboardKey="";
  sealed class GearNamedOption {public string Name,Value;public override string ToString(){return Name;}}
  string[] GearOptions(Dictionary<string,object> state,string name){var values=GearArray(GearMap(state,"settingOptions"),name);return values==null?new string[0]:values.Select(v=>Convert.ToString(v,CultureInfo.InvariantCulture)).ToArray();}
  string GearFriendlyKey(string value){if(value==null)return "未读回";if(value.StartsWith("Key",StringComparison.Ordinal)&&value.Length==4)return value.Substring(3);if(value.StartsWith("Digit",StringComparison.Ordinal))return value.Substring(5);switch(value){case "Disabled":case "KeyDisabled":return "禁用";case "Default":return "默认";case "leftButton":case "MouseClickLeft":return "左键";case "rightButton":case "MouseClickRight":return "右键";case "middleButton":case "MouseClickMiddle":return "中键";case "sideKeyLeftBackward":case "MouseLeftBackward":return "后退侧键";case "sideKeyLeftForward":case "MouseLeftForward":return "前进侧键";case "dpi1":case "MouseDPISwitch":return "DPI 切换";case "scrollUp":case "MouseScrollUp":return "滚轮向上";case "scrollDown":case "MouseScrollDown":return "滚轮向下";case "ShiftMode":return "Shift 模式";case "LeverUp":return "旋钮上";case "LeverMid":return "旋钮按下";case "LeverDown":return "旋钮下";default:return value;}}
  ComboBox GearNamedChoices(IEnumerable<string> options,string current){var box=new ComboBox{Foreground=Brush("#151515"),Background=Brush("#F1F1F1"),Padding=new Thickness(8),Margin=new Thickness(0,0,12,0),MinWidth=120};box.Items.Add(new GearNamedOption{Name="未读回 / 请选择",Value=""});foreach(string value in options){var option=new GearNamedOption{Name=GearFriendlyKey(value),Value=value};box.Items.Add(option);if(value==current)box.SelectedItem=option;}if(box.SelectedIndex<0)box.SelectedIndex=0;return box;}
  static string GearSelectedName(ComboBox box){var option=box.SelectedItem as GearNamedOption;return option==null?"":option.Value;}
  void OriginalGearBindings(StackPanel target,string kind,Dictionary<string,object> state){
   var snapshot=GearMap(state,"snapshot");if(kind=="mouse"){foreach(bool shifted in new[]{false,true}){target.Children.Add(Label(shifted?"Shift 模式":"按键",18,text));var bindings=GearMap(snapshot,shifted?"shiftButtonBindings":"buttonBindings");foreach(string button in GearOptions(state,"buttonSources")){string source=button;var binding=GearMap(bindings,source);var choice=GearNamedChoices(GearOptions(state,"buttonTargets"),OriginalStateText(binding,"target",""));var row=new Grid{Margin=new Thickness(0,8,0,8)};row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});row.Children.Add(FeatureField(GearFriendlyKey(source),choice));var apply=Button("应用",async()=>{string selected=GearSelectedName(choice);if(selected.Length>0)await SetGearSetting(kind,state,"buttonBinding",new Dictionary<string,object>{{"button",source},{"target",selected},{"shift",shifted}});});apply.IsEnabled=binding!=null&&CanApplyGear(state,"buttonBinding");apply.VerticalAlignment=VerticalAlignment.Bottom;Grid.SetColumn(apply,1);row.Children.Add(apply);target.Children.Add(row);}}return;}
   var sources=GearOptions(state,"keySources");var input=GearNamedChoices(sources,selectedKeyboardKey);input.SelectionChanged+=(s,e)=>{selectedKeyboardKey=GearSelectedName(input);ShowPage(page);};target.Children.Add(FeatureField("原按键",input));var read=Button("读取所选按键",async()=>{if(selectedKeyboardKey.Length>0)await ReadOriginalKeyBinding(state,selectedKeyboardKey);});read.IsEnabled=GearOnline(state)&&!busy&&!render;target.Children.Add(read);
   var current=GearMap(snapshot,"keyBinding");string observedSource=OriginalStateText(current,"source","");var output=GearNamedChoices(GearOptions(state,"keyTargets"),observedSource==selectedKeyboardKey?OriginalStateText(current,"target",""):"");target.Children.Add(FeatureField("映射到",output));var set=Button("应用按键映射",async()=>{string source=selectedKeyboardKey,value=GearSelectedName(output);if(source.Length>0&&value.Length>0)await SetGearSetting(kind,state,"keyBinding",new Dictionary<string,object>{{"source",source},{"target",value}});},true);set.IsEnabled=current!=null&&observedSource.Length>0&&observedSource==selectedKeyboardKey&&CanApplyGear(state,"keyBinding");target.Children.Add(set);target.Children.Add(Paragraph("逐键读取后应用；硬件宏绑定仍未接通。",11,muted));
  }
  async Task ReadOriginalKeyBinding(Dictionary<string,object> state,string source){if(busy||closing||render||!GearOnline(state))return;busy=true;status.Text="正在读取所选按键…";try{var reply=await gearWorker.Request<SdkReply>(new Dictionary<string,object>{{"op","read"},{"kind","keyboard"},{"deviceId",OriginalStateText(state,"deviceId","")},{"setting","keyBinding"},{"value",new Dictionary<string,object>{{"source",source}}}});if(!reply.ok||reply.data==null)throw new InvalidOperationException(SdkError(reply.error));reply.data["capturedAt"]=DateTime.Now.ToString("HH:mm:ss");gearStates["keyboard"]=reply.data;Log("按键读取完成，请查看是否返回映射。");}catch(Exception ex){gearStates.Remove("keyboard");Log("按键读取失败："+ex.Message);}finally{busy=false;if(!closing)ShowPage(page);}}
  void OriginalGearOled(StackPanel target,Dictionary<string,object> state){var snapshot=GearMap(state,"snapshot");AddGearFlag(target,"keyboard",state,"oledEnabled","OLED 屏幕");AddGearNumber(target,"keyboard",state,"oledBrightness","亮度（%）",0,100);string[] modes={"动画","时钟","笔记本电量","硬件信息","按键次数"};AddGearMappedChoice(target,"keyboard",state,"oledMode","显示模式",modes,new[]{0,1,2,3,4});AddGearChoice(target,"keyboard",state,"oledPreset","内置动画",new[]{"0","1","2","3","4","5"});AddGearFlag(target,"keyboard",state,"oledKpsEnabled","动画随打字速度变化（KPS）");AddGearModeSwitches(target,"keyboard",state,"oledModeEnabled","oledModeStates",modes);var items=GearMap(snapshot,"oledBarInfo");foreach(string item in GearOptions(state,"oledBarItems")){string key=item;AddGearObjectFlag(target,"keyboard",state,"oledBarItem",GearFriendlyKey(key),OriginalStateFlag(items,key),"item",key);}target.Children.Add(Paragraph("自定义图像、动画上传和软件监控内容尚未接通。",11,muted));}
  void OriginalGearLever(StackPanel target,Dictionary<string,object> state){string[] labels={"媒体音量","媒体播放","按键区域亮度","OLED 亮度","切换灯效","主板风扇","AIO 风扇","自定义"};AddGearMappedChoice(target,"keyboard",state,"leverMode","旋钮功能",labels,new[]{0,1,2,3,4,5,6,7});AddGearModeSwitches(target,"keyboard",state,"leverModeEnabled","leverModeStates",labels);}
  void AddGearModeSwitches(StackPanel target,string kind,Dictionary<string,object> state,string setting,string getter,string[] labels){var flags=GearArray(GearMap(state,"snapshot"),getter);for(int i=0;i<labels.Length;i++){int index=i;bool? current=flags!=null&&i<flags.Length&&flags[i] is bool?(bool?)flags[i]:null;AddGearObjectFlag(target,kind,state,setting,labels[i]+" · 可切换",current,"mode",index);}}
  void AddGearObjectFlag(StackPanel target,string kind,Dictionary<string,object> state,string setting,string title,bool? current,string key,object index){var row=Row();var check=new CheckBox{Content=title,IsThreeState=true,IsChecked=current,Foreground=text,Margin=new Thickness(0,8,16,8)};row.Children.Add(check);var apply=Button("应用",async()=>{if(check.IsChecked.HasValue)await SetGearSetting(kind,state,setting,new Dictionary<string,object>{{key,index},{"enabled",check.IsChecked.Value}});});apply.IsEnabled=current.HasValue&&CanApplyGear(state,setting);row.Children.Add(apply);target.Children.Add(row);}
  void OriginalGearZone(StackPanel target,Dictionary<string,object> state){var zone=GearMap(GearMap(state,"snapshot"),"zoneSettings");var enabled=new CheckBox{Content="Zone Mode",IsThreeState=true,IsChecked=OriginalStateFlag(zone,"enabled"),Foreground=text,Margin=new Thickness(0,8,0,16)};target.Children.Add(enabled);var rate=FeatureCombo(new[]{"未读回","125","250","500","1000","2000","4000","8000"},OriginalStateText(zone,"pollingRate","未读回"));target.Children.Add(FeatureField("轮询率（Hz）",rate));TextBox x=FeatureText(OriginalStateText(zone,"dpi","")),y=FeatureText(OriginalStateText(zone,"dpiY",""));target.Children.Add(FeatureField("水平 DPI",x));target.Children.Add(FeatureField("垂直 DPI",y));string power=OriginalStateText(zone,"txPower","");var tx=FeatureCombo(new[]{"未读回","全功率","环境自适应"},power=="0"?"全功率":power=="1"?"环境自适应":"未读回");target.Children.Add(FeatureField("发射功率",tx));var apply=Button("应用 Zone Mode",async()=>{int dpi,dpiY,polling;if(!enabled.IsChecked.HasValue||!Int32.TryParse(x.Text,out dpi)||!Int32.TryParse(y.Text,out dpiY)||dpi<100||dpi>65000||dpiY<100||dpiY>65000||!Int32.TryParse(Convert.ToString(rate.SelectedItem),out polling)||tx.SelectedIndex<1){Log("请填写 Zone Mode 的全部设置，DPI 为 100 至 65000。");return;}await SetGearSetting("mouse",state,"zoneSettings",new Dictionary<string,object>{{"enabled",enabled.IsChecked.Value},{"pollingRate",polling},{"dpi",dpi},{"dpiY",dpiY},{"txPower",tx.SelectedIndex-1}});},true);apply.IsEnabled=zone!=null&&CanApplyGear(state,"zoneSettings");target.Children.Add(apply);}
 }
}
